-- Steps 4+5 read-back (READ ONLY): Plan-2a equations + Plan-2b widget configs
select w.code as ws, e.equation_number, e.output_symbol, left(e.formula, 60) as formula, e.input_symbols::text as inputs from equations e join worksheet_templates w on w.id = e.worksheet_template_id join standards s on s.id = w.standard_id where s.code = 'DWA-A-138-1' and w.code = 'A138-07' order by e.equation_number;
select w.code as ws, e.equation_number, e.output_symbol, e.verification_status from equations e join worksheet_templates w on w.id = e.worksheet_template_id join standards s on s.id = w.standard_id where s.code = 'VSME' and w.code = 'VSME-B04.100' order by e.equation_number;
select w.code as ws, f.symbol, f.visible_when from fields f join worksheet_templates w on w.id = f.worksheet_template_id join standards s on s.id = w.standard_id where s.code = 'DWA-A-138-1' and w.code = 'A138-12' and f.visible_when is not null order by f.symbol;
select s.code as standard, w.code as ws, f.symbol, f.widget, f.data_type, (f.ui_config is not null) as has_ui_config, (f.lookup is not null) as has_lookup from fields f join worksheet_templates w on w.id = f.worksheet_template_id join standards s on s.id = w.standard_id where f.symbol in ('surface_inventory', 'pollutant_register', 'rainfall_table_ref', 'ac_as_ratio_limit') and f.active order by 1, 2, 3;
